"""业务逻辑：添加、列出、汇总。"""
import datetime

from . import storage


def _validate_date(date_str):
    """校验日期格式 YYYY-MM-DD，非法则抛 ValueError。"""
    try:
        datetime.datetime.strptime(date_str, "%Y-%m-%d")
    except ValueError:
        raise ValueError("日期格式错误，应为 YYYY-MM-DD：%s" % date_str)


def add_record(amount, record_type, category, date, note=""):
    """添加一条记录，返回其 id。删除后已有 id 保持不变（取历史最大 id + 1）。"""
    if record_type not in ("income", "expense"):
        raise ValueError("类型必须是 income 或 expense：%s" % record_type)
    try:
        amount = float(amount)
    except (TypeError, ValueError):
        raise ValueError("金额必须是数字：%s" % amount)
    if amount <= 0:
        raise ValueError("金额必须大于 0：%s" % amount)
    _validate_date(date)

    records = storage.load_records()
    next_id = max((r["id"] for r in records), default=0) + 1
    record = {
        "id": next_id,
        "date": date,
        "type": record_type,
        "category": category,
        "amount": amount,
        "note": note,
    }
    records.append(record)
    storage.save_records(records)
    return next_id


def list_records():
    """按日期升序返回全部记录（同日按 id 升序）。"""
    return sorted(storage.load_records(), key=lambda r: (r["date"], r["id"]))


def summary():
    """返回 (总收入, 总支出, 结余)。"""
    income = 0.0
    expense = 0.0
    for r in storage.load_records():
        if r["type"] == "income":
            income += r["amount"]
        else:
            expense += r["amount"]
    return income, expense, income - expense

